int numberIntersectedPrimitives(const Tree& tree, const BoundingBox3& b) {
    // Convert BoundingBox3 to CGAL's bounding box format
    typename Tree::FT min_x = b.minX();
    typename Tree::FT min_y = b.minY();
    typename Tree::FT min_z = b.minZ();
    typename Tree::FT max_x = b.maxX();
    typename Tree::FT max_y = b.maxY();
    typename Tree::FT max_z = b.maxZ();

    // Create CGAL point for the bbox min and max
    typename Tree::Geom_traits::Point_3 min_point(min_x, min_y, min_z);
    typename Tree::Geom_traits::Point_3 max_point(max_x, max_y, max_z);

    // Create a CGAL bbox
    typename Tree::Geom_traits::Iso_cuboid_3 bbox(min_point, max_point);

    // Count intersected primitives
    return tree.number_of_intersected_primitives(bbox);
}

int numberIntersectedPrimitives(const Tree& tree, const BoundingBox3& b) {
    // Create a counter class to count intersections
    struct BBoxIntersectionsCounter {
        int count;

        BBoxIntersectionsCounter() : count(0) {}

        template <class Query>
        void operator()(const Query& query) {
            ++count;
        }
    };

    // Use the callback approach to count intersections
    BBoxIntersectionsCounter counter;
    tree.report_intersected_primitives(b, counter);
    return counter.count;
}

int numberIntersectedPrimitives(const Tree& tree, const BoundingBox3& b) {
    // Convert BoundingBox3 to CGAL's Iso_cuboid_3
    typename Tree::Geom_traits::Iso_cuboid_3 cgal_bbox(
        b.minX(), b.minY(), b.minZ(), 
        b.maxX(), b.maxY(), b.maxZ()
    );

    // Count intersected primitives using CGAL's tree.number_of_intersected_primitives with the bounding box
    return tree.number_of_intersected_primitives(cgal_bbox);
}

